/// `opdbus/wake/<owner-key>` topic through the `emqx` plugin, best effort
/// and off the commit path. The committed SHM document is the truth; a
/// broker outage only delays the UI.
pub(crate) fn emqx_doorbell() -> Doorbell { … }

