async fn prepare_ticket(
    engine: &MutationEngine, plugin: &str, method: &str, arguments: Value,
    caller: &GhostbridgeIdentity, capability: Option<&str>, proof: Option<BoundOracleProof>,
    source_schema_hash: &str, operation: Option<tched_fs::mounted::AdmittedOperation>, deadline: Deadline,
    origin: Option<Arc<Ticket>>, response: Option<crate::chat_response_turns::PendingTurn>,
) -> Result<(Arc<Ticket>, crate::sealed_schema_reader::ManifestPinnedSchemaDocument)> {
    // Retired vendor extension: stale captures must not execute it through the
    // generic command runner after its custom admission callback is removed.
    ensure!(plugin != "threetched" || method != "stateless-generate",
        "patched foundation generation is unsupported; no native effect was attempted");
    let application = matches!(&operation, Some(tched_fs::mounted::AdmittedOperation::Application { .. }));
    let direct = operation.is_none();
    let bytes = tickets().bytes.clone().try_acquire_many_owned(TICKET_CHARGE)
        .context("mounted ingress byte capacity exhausted")?;
    let session = crate::project_dispatch::verified_session(engine, &caller.principal_id,
        Some(&caller.session_id), Some(&caller.session_genesis)).await?;
    let pinned = crate::sealed_schema_reader::read_manifest_pinned_schema_document(
        &crate::sealed_schema_reader::blob_catalog_dir_from_env(), plugin)?;
    ensure!(pinned.schema_hash == source_schema_hash, "source seal changed before mounted ingress");
    let capability = if direct {
        pinned.schema.methods.get(method).context("direct guest method absent")?.required_capability.as_deref()
    } else { capability };
    let declaration = crate::method_contract_admission::admit_pinned_compiled_method(&pinned, plugin, method, capability)?;
    crate::method_contract_admission::validate_admitted_arguments(&declaration, &arguments)?;
    if let Some(capability) = capability {
        ensure!(crate::interceptor::load_capability_grants(&caller.principal_id).contains(capability), "mounted invocation requires current exact grant");
    }
    if let Some(proof) = &proof {
        crate::interceptor::revalidate_bound_oracle(engine, proof, &caller.principal_id,
            Some(&caller.session_id), Some(&caller.session_genesis), true).await?;
    }
    let (binding, mounts, root) = {
        let lifecycle = crate::identity_sled_dispatch::guard_identity_incus_target(engine, &session).await?;
        let _host = engine.lock_host_observation().await;
        let root = lifecycle.verify_under_host_lock("exec_instance").await?.context("guest storage provenance absent")?;
        root.require_guest_ingress()?;
        let sled = crate::identity_sled_dispatch::stored_session(engine, &session).await?.context("caller identity disappeared")?;
        let binding = current_container_binding(&sled).await?;
        let process = binding.init.clone();
        let check: Arc<dyn Fn() -> Result<()> + Send + Sync> = Arc::new(move || process.revalidate());
        let mounts = [
            MountedNamespace::open_in_process(binding.init.pid, GUEST_MOUNT_PATHS[0].as_ref(), check.clone())?,
            MountedNamespace::open_in_process(binding.init.pid, GUEST_MOUNT_PATHS[1].as_ref(), check)?,
        ];
        (binding, mounts, root)
    };
    let owner = declared_mount_index([mounts[0].contains_plugin(plugin)?, mounts[1].contains_plugin(plugin)?])?;
    ensure!(mounts[owner].schema_hash(plugin)? == pinned.schema_hash, "guest projected schema differs from admission");
    let pins = [mounts[0].pin()?, mounts[1].pin()?];
    deadline.remaining()?;
    let body = if let Some(operation) = operation {
        let mut body = BoundedBody(Vec::new());
        serde_json::to_writer(&mut body, &MountedInvocation {
            plugin: plugin.to_owned(), method: method.to_owned(),
            schema_hash: pinned.schema_hash.clone(), capability: capability.map(str::to_owned),
            arguments: arguments.clone(), mount: pins[owner].clone(), operation,
        })?;
        Some(String::from_utf8(body.0)?)
    } else { None };
    let ticket = Arc::new(Ticket { binding, mounts, pins, actor: caller.principal_id.clone(),
        capability: capability.map(str::to_owned), proof, plugin: plugin.to_owned(), method: method.to_owned(),
        schema_hash: pinned.schema_hash.clone(), deadline, arguments, response,
        backend_execution: application, origin,
        payload: Mutex::new(Payload { cancelled: false, body, dispatched: direct }), _bytes: bytes, _root: root });
    readmit(engine, &ticket).await?;
    Ok((ticket, pinned))
}

