pub(crate) async fn admit_transport(
    engine: &MutationEngine, kernel: Option<&LungsIdentity>, caller: &GhostbridgeIdentity,
    plugin: &str, method: &str, arguments: &str, metadata: CallMetadata, started: Instant,
) -> Result<CallContext> {
    metadata.validate()?;
    let mut deadline = Deadline::received(started, metadata.remaining_ms)?;
    let mut owned_lease = None;
    let ticket = if let Some(id) = metadata.admitted_operation_id {
        let kernel = kernel.context("mounted admission requires a kernel-bound lungs connection")?;
        let ticket = tickets().entries.lock().unwrap_or_else(|error| error.into_inner())
            .get(&id).cloned().context("mounted admission is unavailable")?;
        let resolved = kernel.resolve().await.map_err(anyhow::Error::from)?;
        let Binding::Container(binding) = kernel.binding.get().context("guest binding absent")? else {
            anyhow::bail!("mounted admission requires the original guest")
        };
        ensure!(resolved == *caller && caller.principal_id == ticket.actor
            && same_binding(binding, &ticket.binding), "mounted admission belongs to another caller");
        ensure!(!ticket.backend_execution && ticket.plugin == plugin && ticket.method == method
            && ticket.schema_hash == metadata.source_schema_hash,
            "mounted admission does not name this method contract");
        let arguments: Value = serde_json::from_str(arguments)?;
        ensure!(arguments == ticket.arguments, "mounted admission arguments changed");
        readmit(engine, &ticket).await?;
        deadline = deadline.clamp(ticket.deadline);
        deadline.remaining()?;
        {
            let mut payload = ticket.payload.lock().unwrap_or_else(|error| error.into_inner());
            ensure!(!payload.cancelled && payload.body.is_none() && !payload.dispatched,
                "mounted admission is not available for a first dispatch");
            payload.dispatched = true;
        }
        Some((id, ticket))
    } else if let Some(kernel) = kernel.filter(|kernel| matches!(kernel.binding.get(), Some(Binding::Container(_)))) {
        let resolved = kernel.resolve().await.map_err(anyhow::Error::from)?;
        let Binding::Container(binding) = kernel.binding.get().context("direct guest binding absent")? else {
            anyhow::bail!("direct invocation requires its guest kernel binding")
        };
        ensure!(resolved == *caller && kernel.peer.mount_namespace == binding.init.mount_namespace,
            "direct invocation belongs to another guest");
        kernel.require_guest_root()?;
        let arguments: Value = serde_json::from_str(arguments)?;
        let response = if let Some(turn_id) = metadata.response_turn_id {
            if plugin == "chat_response" {
                ensure!(arguments.get("turn_id").and_then(Value::as_str) == Some(turn_id.as_str()),
                    "response metadata and operation name different turns");
            } else {
                ensure!(plugin == "threetched" && method == "config.get",
                    "response reference is not valid for this operation");
            }
            let pending = engine.chat_turns().pending_for_responder(&turn_id, &caller.principal_id)?;
            validate_response(engine, &pending, &caller.principal_id).await?;
            Some(pending)
        } else {
            None
        };
        let (ticket, _) = prepare_ticket(engine, plugin, method, arguments, caller, None, None,
            &metadata.source_schema_hash, None, deadline, None, response).await?;
        kernel.require_guest_root()?;
        ensure!(same_binding(binding, &ticket.binding)
            && kernel.resolve().await.map_err(anyhow::Error::from)? == *caller,
            "direct guest changed during admission");
        let lease = register_ticket(ticket.clone())?;
        let id = lease.id.clone();
        owned_lease = Some(lease);
        Some((id, ticket))
    } else {
        ensure!(metadata.response_turn_id.is_none(), "response reference requires a guest kernel binding");
        None
    };
    Ok(CallContext { deadline, ticket, _lease: owned_lease })
}

struct BoundedBody(Vec<u8>);
impl std::io::Write for BoundedBody {
    fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> {
        if bytes.len() > (1024 * 1024 + 16 * 1024usize).saturating_sub(self.0.len()) {
