//! Ephemeral input handoff for one already-admitted mounted operation.
//! No result storage, dispatch, replay, recovery or provisioning lives here.
use super::{ContainerBinding, LungsIdentity, Binding, current_container_binding, same_binding};
use std::{collections::BTreeMap, sync::{Arc, Mutex, LazyLock}, time::{Duration, Instant}};
use anyhow::{Context, Result, ensure};
use serde_json::Value;
use tokio::sync::{OwnedSemaphorePermit, Semaphore};
use tched_fs::mounted::{GuestMountSnapshot, MountPin, MountedInvocation, MountedNamespace, GUEST_MOUNT_PATHS, declared_mount_index};
use crate::{mutation_engine::MutationEngine, interceptor::GhostbridgeIdentity, oracle_assertion::BoundOracleProof};
use tched_fs::invocation::{CallMetadata, Deadline};
use op_plugins::state_plugins::chat_response_methods::{ResponseMode, SubmitTurnInput};
