const MAX_TICKETS: usize = 32;
const BYTE_LIMIT: usize = 64 * 1024 * 1024;
const TICKET_CHARGE: u32 = 2 * (1024 * 1024 + 16 * 1024);
struct Payload { cancelled: bool, body: Option<String>, dispatched: bool }
struct Ticket {
    binding: ContainerBinding,
    mounts: [GuestMountSnapshot; 2],
    pins: [MountPin; 2],
    actor: String,
    capability: Option<String>,
    proof: Option<BoundOracleProof>,
    plugin: String,
    method: String,
    schema_hash: String,
    deadline: Deadline,
    arguments: Value,
    response: Option<crate::chat_response_turns::PendingTurn>,
    backend_execution: bool,
    // The initiating operation remains separately bound when responder execution
    // occurs in another guest. This is ephemeral admission, not correlation/replay.
…
}

