let grants = crate::interceptor::load_capability_grants(&self.0.actor);
let mut targets = serde_json::Map::new();
// A prompt's consumer allowlist, never declarations or a binary catalog.
// All shapes, capabilities and hashes come from the actual human mount/seal.
for (plugin, methods) in [
    ("chat_response", &["start_conversation", "submit_turn", "get_conversation", "get_turn_response"][..]),
    ("model_registry", &["list_providers", "list_models"][..]),
    ("threetched", &["config.get"][..]),
] {
    let owner = declared_mount_index([mounts[0].contains_plugin(plugin)?, mounts[1].contains_plugin(plugin)?])?;
    let pinned = crate::sealed_schema_reader::read_manifest_pinned_schema_document(
        &crate::sealed_schema_reader::blob_catalog_dir_from_env(), plugin)?;
    ensure!(mounts[owner].schema_hash(plugin)? == pinned.schema_hash, "human target differs from current seal");
    let declarations = methods.iter().map(|method| {
        let declaration = pinned.schema.methods.get(*method)
            .with_context(|| format!("application target {plugin}.{method} is absent"))?;
        Ok(((*method).to_owned(), serde_json::json!({
            "capability": declaration.required_capability,
            "arguments": declaration.args, "returns": declaration.returns,
            "currently_granted": declaration.required_capability.as_ref().is_none_or(|capability| grants.contains(capability)),
        })))
    }).collect::<Result<serde_json::Map<String, Value>>>()?;
    targets.insert(plugin.to_owned(), serde_json::json!({
        "schema_hash": pinned.schema_hash, "methods": declarations,
    }));
}

