    pub(crate) async fn catalog(&self, engine: &MutationEngine, input: op_plugins::state_plugins::tched_fs::GetCatalogInput) -> Result<Value> {
        use op_plugins::state_plugins::tched_fs::{CatalogOperation, CatalogPlugin, CatalogState, CatalogView, GetCatalogOutput};
        self.revalidate(engine).await?;
        let (_, ticket) = self.ticket.as_ref().context("catalog discovery requires the caller's admitted guest mounts")?;
        let grants = crate::interceptor::load_capability_grants(&ticket.actor);
        let mut views = Vec::with_capacity(2);
        let mut found = false;
        for mount in &ticket.mounts {
            let pin = mount.pin()?;
            let catalog = mount.catalog()?;
            let objects = catalog["objects"].as_object().context("mounted catalog objects missing")?;
            let mut plugins = Vec::new();
            for (plugin, object_hash) in objects {
                if input.plugin.as_deref().is_some_and(|selected| selected != plugin) { continue; }
                ensure!(!found || input.plugin.is_none(), "plugin appears in more than one mounted view");
                found = true;
                let schema = mount.schema(plugin)?;
                let schema_hash = mount.schema_hash(plugin)?;
                let pinned = crate::sealed_schema_reader::read_manifest_pinned_schema_document(
                    &crate::sealed_schema_reader::blob_catalog_dir_from_env(), plugin)?;
                ensure!(schema_hash == pinned.schema_hash && serde_json::to_value(&schema)? == serde_json::to_value(&pinned.schema)?,
                    "mounted discovery differs from the current sealed plugin");
                let prefix = format!("plugins/{}", tched_fs::namespace::encode_component(plugin));
                let operations = schema.methods.iter().map(|(method, declaration)| {
                    let path = format!("{prefix}/operations/{}", tched_fs::namespace::encode_component(method));
                    CatalogOperation {
                        method: method.clone(), call_path: format!("{path}/call"),
                        metadata_path: format!("{path}/metadata.json"),
                        currently_granted: declaration.required_capability.as_deref().is_none_or(|capability| grants.contains(capability)),
                    }
                }).collect();
                plugins.push(CatalogPlugin {
                    plugin_id: plugin.clone(),
                    object_hash: object_hash.as_str().context("mounted object hash missing")?.to_owned(),
                    schema_hash, schema: serde_json::to_value(schema)?, operations, state: CatalogState::NotRequested,
                });
            }
            views.push(CatalogView { view_id: pin.view_id, source_catalog_hash: pin.source_catalog_hash,
                source_catalog_generation: pin.source_catalog_generation, plugins });
        }
        ensure!(input.plugin.is_none() || found, "plugin is absent from the caller's mounted catalog");
        let mut bytes = BoundedBody(Vec::new());
        serde_json::to_writer(&mut bytes, &GetCatalogOutput { views })?;
        self.revalidate(engine).await?;
        serde_json::from_slice(&bytes.0).context("serialize mounted catalog")
    }
}

