95:pub(crate) async fn dispatch(
96:    engine: &MutationEngine,
97:    method: &str,
98:    args: &serde_json::Value,
99:    actor: &str,
100:    capability: Option<&str>,
101:    session: Option<&str>,
102:    genesis: Option<&str>,
103:    admitted_schema: &AdmittedContract,
104:) -> Result<serde_json::Value> {
105:    let mutation = is_mutation(method);
106:    let _operation = CRON_OPERATION.lock().await;
107:    let caller = crate::tched_router_admission::RouterCaller {
108:        actor: actor.to_owned(),
109:        capability: capability.map(str::to_owned),
110:        session: session.map(str::to_owned),
111:        genesis: genesis.map(str::to_owned),
112:    };
113:    let pinned = crate::tched_router_admission::readmit_call(
114:        engine,
115:        admitted_schema,
116:        PLUGIN,
117:        method,
118:        &caller,
119:    )
120:    .await?;
121:    let pin = SealPin {
122:        schema_hash: pinned.schema_hash,
123:        schema_json: pinned.blob.schema_json,
124:    };
125:    let service = CronMethods::new(Arc::new(TchedRouterCronGateway::production()));
126:    let mut receipt = service.dispatch_observed(method, args).await?;
127:
128:    let expected_hash = pin.schema_hash.clone();
129:    let post_seal = blocking(move || seal_is_unchanged(&pin)).await;
130:    if post_seal.is_err() {
131:        if mutation {
132:            if receipt
133:                .output
134:                .get("disposition")
135:                .and_then(serde_json::Value::as_str)
136:                != Some("indeterminate")
137:            {
138:                mark_publication_unverified(method, &mut receipt.output)?;
139:            }
140:            return Ok(receipt.output);
141:        }
142:        return post_seal.map(|_| receipt.output);
143:    }
144:
145:    if let Some(state) = receipt.state {
146:        let state = simd_json::serde::to_owned_value(state)?;
147:        if let Err(_error) = engine
148:            .process_observed_state(PLUGIN, state, expected_hash)
149:            .await
150:        {
151:            if mutation {
152:                mark_publication_unverified(method, &mut receipt.output)?;
153:                return Ok(receipt.output);
154:            }
155:            anyhow::bail!("cron observation could not be committed to authoritative state");
156:        }
157:    }
158:    Ok(receipt.output)
