pub(crate) fn request(operation: &str, actor: &str, session: &str, genesis: &str,
    kind: &str, target: &str, mut body: Value) -> Result<NativeCreationRequest> {
…
    Ok(NativeCreationRequest { operation_id: operation.into(), actor_id: actor.into(),
        caller_session: session.into(), caller_genesis: genesis.into(), owner_kind: kind.into(),
        logical_target: target.into(), schema_hash: pin.schema_hash, request_digest, request_json,
        reserved_name: reserved_chatbot.then(|| "3tchedCtlChatbot".to_owned()) })
}

pub(crate) fn container_label(record: &NativeCreationRecord) -> Result<Option<String>> {
    let body: Value = serde_json::from_str(&record.request.request_json)?;
    match body["config"].get("user.opdbus.naming_version") {
        None => Ok(None),
        Some(Value::String(version)) if version == "1" => Ok(Some(
            incus::container_label_for_native_name(&record.name)
                .context("numbered creation has an invalid native name")?)),
        _ => anyhow::bail!("unsupported native naming policy"),
    }
}

