pub(crate) fn verify_assigned_arrival(
    facts: ArrivalFacts<'_>,
    proof: &crate::oracle_assertion::BoundOracleProof,
    now: i64,
) -> Result<ScribeVerdict, ScribeRejection> { … }

fn verify_target(facts: ArrivalFacts<'_>) -> Result<ScribeVerdict, ScribeRejection> { … }

